mkdir -p /out; cat > /tmp/render.py <<'EOF'
import tomllib, json, datetime, pathlib
UNSET = "__unset__"
def merge(base, over):
    out = dict(base)
    for k, v in over.items():
        if v == UNSET:
            out.pop(k, None)
        elif isinstance(v, dict):
            b = out.get(k)
            out[k] = merge(b if isinstance(b, dict) else {}, v)
        else:
            out[k] = v
    return out
def conv(o):
    if isinstance(o, dict): return {k: conv(v) for k, v in o.items()}
    if isinstance(o, list): return [conv(v) for v in o]
    if isinstance(o, (datetime.date, datetime.time)): return o.isoformat()
    return o
base = tomllib.loads(pathlib.Path("/config/base.toml").read_text(encoding="utf-8"))
names = []
for f in sorted(pathlib.Path("/config/env").glob("*.toml")):
    over = tomllib.loads(f.read_text(encoding="utf-8"))
    data = conv(merge(base, over))
    pathlib.Path(f"/out/{f.stem}.json").write_text(
        json.dumps(data, indent=2, sort_keys=True, ensure_ascii=False) + "\n", encoding="utf-8")
    names.append(f.stem)
pathlib.Path("/out/index.txt").write_text("".join(n + "\n" for n in sorted(names)), encoding="utf-8")
EOF
python3 /tmp/render.py && ls /out && cat /out/index.txt /out/dev.json /out/prod.json

